function editorRoots(){return editor.Pages.getAll().map(page=>page.getMainComponent?.()).filter(Boolean);}
function ensureEditorNodeIds(){return ensureStableNodeIds(editorRoots(),{onRepair:({previous,next})=>console.warn('Forma repaired duplicate node ID',{previous,next})});}
function canvasComponentStyle(component){const inline=component?.getStyle?.()||{},element=component?.view?.el,view=element?.ownerDocument?.defaultView;if(!element||!view)return inline;const result={...inline};try{const computed=view.getComputedStyle(element);['left','top','width','height','position'].forEach(key=>{const value=computed.getPropertyValue(key);if(value&&value!=='auto')result[key]=value;});}catch{}if(!parseFloat(result.width)&&element.offsetWidth)result.width=`${element.offsetWidth}px`;if(!parseFloat(result.height)&&element.offsetHeight)result.height=`${element.offsetHeight}px`;return result;}
function zoomComponent(){return findCanvasBoard(editor.getWrapper().components(),editor.getWrapper());}
function zoomFrame(){return zoomComponent()?.view?.el||null;}
function zoomFrameSize(){const frame=zoomFrame(),size=canvasComponentStyle(zoomComponent());return frame?{width:parseFloat(size.width)||frame.offsetWidth,height:parseFloat(size.height)||frame.offsetHeight}:null;}
function selectBoard(){const board=zoomComponent();selected=board;if(board)editor.select(board);syncInspector();}
async function saveProjectToFolder(options){if(window.formaApi?.workspace?.isActive())return window.formaApi.workspace.flush();const value=await projectStore.saveToFolder(options);if(options?.newCopy&&value?.id)await openProject(value.id);return value;}
function scheduleSave(){documentHistory?.schedule();const workspace=window.formaApi?.workspace;if(workspace?.isActive()){if(!workspace.applying)return workspace.schedule();return;}return projectStore?.scheduleSave();}
function restoreHistory(snapshot){
  const project=projectState.serialize();project.editor.grapesjs=snapshot.data.editor;project.forma=snapshot.data.forma;project.assets=snapshot.data.assets;project.name=snapshot.data.name;
  editor.loadProjectData(project.editor.grapesjs);projectState.load(project);$('file-name').value=project.name;syncCanvasWrapperExtent();
  const page=editor.Pages.get(snapshot.context?.page);if(page)editor.Pages.select(page);
  ensureEditorNodeIds();assetManager.resolve(editor);selected=undefined;
  const visit=node=>{if(node.get('formaNodeId')===snapshot.context?.node)selected=node;node.components().models.forEach(visit);};editorRoots().forEach(visit);
  if(selected)editor.select(selected);else selectBoard();renderPages();renderLayers();syncInspector();gridOverlay.refresh();zoomController.pageChanged();scheduleSave();
}
async function loadProjects(){const value=await projectStore.listProjects();projectsCache=value.projects||[];$('projects-path').textContent=value.folder||'GrapesJS/projects';renderProjectGrid();}
function renderProjectGrid(){const root=$('projects-grid'),query=$('project-search').value.trim().toLowerCase();root.replaceChildren();const items=projectsCache.filter(project=>project.name.toLowerCase().includes(query));if(!items.length){root.innerHTML='<div class="projects-empty"><span>'+icon('folder',30)+'</span><h3>'+(query?'No matching projects':'No saved projects yet')+'</h3><p>'+(query?'Try another name.':'Choose New project, or save the current design to this folder.')+'</p></div>';renderRecoveryCopies(root);return;}items.forEach(project=>{const card=document.createElement('article');card.className='project-card'+(project.id===currentProjectId?' active':'');const date=new Date(project.updatedAt);card.innerHTML=`<button class="project-open" aria-label="Open ${escapeHtml(project.name)}"><span class="project-thumb">${icon('frame',32)}<b>${project.pages||1}</b></span><span class="project-card-copy"><strong>${escapeHtml(project.name)}</strong><small>${project.pages||1} page${project.pages===1?'':'s'} · ${date.toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'})}</small></span>${project.id===currentProjectId?'<em>Open</em>':''}</button><button class="project-copy" aria-label="Duplicate ${escapeHtml(project.name)}" title="Duplicate">${icon('copy',15)}</button><button class="project-remove" aria-label="Delete ${escapeHtml(project.name)}" title="Delete project">${icon('trash-2',15)}</button>`;card.querySelector('.project-open').onclick=()=>openProject(project.id);card.querySelector('.project-copy').onclick=()=>duplicateStoredProject(project.id);card.querySelector('.project-remove').onclick=()=>deleteStoredProject(project);root.append(card);});renderRecoveryCopies(root);}

function renderRecoveryCopies(root){
  for(const recovery of projectStore.listRecoveryCopies()){
    const card=document.createElement('article');card.className='project-card';
    const label=document.createElement('strong');label.textContent=recovery.project.name+' — recovery copy';card.append(label);
    const downloadButton=document.createElement('button');downloadButton.className='secondary-btn';downloadButton.textContent='Download backup';
    downloadButton.onclick=async()=>{let portable=recovery.project;try{portable=await projectStore.portableProject(recovery.project);}catch{toast('Recovery downloaded. Some original image files are unavailable.');}download(JSON.stringify(portable,null,2),'recovery-'+Date.now()+'.json','application/json');};
    card.append(downloadButton);root.append(card);
  }
}

