// Sibling order is the paint order: the last component is visually on top.
// Move the actual GrapesJS component (never just a DOM row or temporary z-index).
function changeLayerOrder(component, direction){
  if(!component||component===editor.getWrapper()||component.get('locked'))return;
  const parent=component.parent();
  if(!parent||parent.get('locked'))return;
  const siblings=parent.components().models;
  const current=siblings.indexOf(component);
  const destination=current+direction;
  if(current<0||destination<0||destination>=siblings.length)return;
  component.move(parent,{at:destination});
  editor.select(component);
  renderLayers();
  scheduleSave();
}
function moveLayerTo(component,target,position){
  if(!component||!target||component===target||component.get('locked'))return false;
  const parent=component.parent(),targetParent=target.parent();
  if(!parent||parent!==targetParent||parent.get('locked'))return false;
  const siblings=parent.components().models,current=siblings.indexOf(component),targetIndex=siblings.indexOf(target);
  if(current<0||targetIndex<0)return false;
  let destination=position==='above'?targetIndex+1:targetIndex;
  destination=Math.max(0,Math.min(siblings.length-1,destination));
  if(destination===current)return false;
  component.move(parent,{at:destination});
  editor.select(component);
  renderLayers();
  scheduleSave();
  return true;
}
