      row.ondragleave=()=>row.classList.remove('drop-above','drop-below');
      row.ondrop=e=>{if(!layerDrag)return;e.preventDefault();const rect=row.getBoundingClientRect(),above=e.clientY<rect.top+rect.height/2;if(!moveLayerTo(layerDrag.component,c,above?'above':'below'))toast('Drag layers inside the same frame to reorder');layerDrag=null;};
      const exp=document.createElement('span');exp.className='layer-expander';
      if(kids.length)exp.innerHTML=icon(collapsed.has(c.cid)?'chevron-right':'chevron-down',10);
      exp.onclick=e=>{e.stopPropagation();if(collapsed.has(c.cid))collapsed.delete(c.cid);else collapsed.add(c.cid);renderLayers();};
      row.append(exp);
      const sym=document.createElement('span');
      sym.innerHTML=icon(c.get('type')==='text'?'type':c.get('type')==='image'?'diamond':depth===0?'frame':'square',14);
      row.append(sym);
