function keydown(e){const editing=editor.getEditing?.();if(e.key==='Escape'&&editing){e.preventDefault();e.stopPropagation();const disable=editing.view?.disableEditing?.();if(disable&&typeof disable.then==='function')disable.finally(()=>editor.getModel?.().setEditing?.(null));else editor.getModel?.().setEditing?.(null);setActiveTool('select',{quiet:true});$('file-menu').hidden=true;return;}if(e.target.closest('input,select,textarea,[contenteditable="true"]')||$('preview-dialog').open)return;const k=e.key.toLowerCase(),mod=e.ctrlKey||e.metaKey;if(window.formaApi?.workspace?.isActive()&&!window.formaApi.workspace.canWrite()&&((mod&&['z','d','s'].includes(k))||['delete','backspace','r','o','t','f','p','l','s','k'].includes(k)||k.startsWith('arrow'))){e.preventDefault();return;}if(e.code==='Space'&&!e.repeat){e.preventDefault();toolState.beginTemporary('pan');return;}if(e.shiftKey&&(e.code==='Digit1'||k==='1'||k==='!')){e.preventDefault();zoomController.fit();return;}if(e.shiftKey&&(e.code==='Digit2'||k==='2'||k==='@')){e.preventDefault();zoomController.fitSelection(()=>editor.getSelected?.());return;}if(mod&&k==='d'){e.preventDefault();duplicate();}else if(mod&&k==='z'){e.preventDefault();e.shiftKey?redo():undo();}else if(mod&&k==='s'){e.preventDefault();scheduleSave();toast('Saved in this browser');}else if(['delete','backspace'].includes(k)){e.preventDefault();deleteSelected();}else if(!mod){if(k==='v')panMode(false);if(k==='h')panMode(toolState.snapshot().persistent!=='pan');const nextTool=toolForShortcut(k,e.shiftKey);if(nextTool){e.preventDefault();setActiveTool(nextTool);return;}if(k==='escape'){panMode(false);$('file-menu').hidden=true;}if(k.startsWith('arrow')&&selected){e.preventDefault();const delta=e.shiftKey?10:1;style({left:(cssNumber(getStyle().left)+(k==='arrowleft'?-delta:k==='arrowright'?delta:0))+'px',top:(cssNumber(getStyle().top)+(k==='arrowup'?-delta:k==='arrowdown'?delta:0))+'px'});}else if(k.startsWith('arrow')){e.preventDefault();const step=e.shiftKey?100:10,delta={x:k==='arrowleft'?step:k==='arrowright'?-step:0,y:k==='arrowup'?step:k==='arrowdown'?-step:0},coords=editor.Canvas.getCoords?.()||{x:0,y:0};zoomController.manualPan();editor.Canvas.setCoords(coords.x+delta.x,coords.y+delta.y);}}}
const keyup=e=>{if(e.code==='Space')toolState.endTemporary('pan');};document.addEventListener('keydown',keydown);document.addEventListener('keyup',keyup);editor.on('canvas:frame:load',({window:win})=>{win.document.addEventListener('keydown',keydown);win.document.addEventListener('keyup',keyup);});
